export function faSvg(name, className = "") {
  const icon = FA_ICONS[name];
  if (!icon) return null;
  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("viewBox", icon.viewBox);
  svg.setAttribute("aria-hidden", "true");
  svg.setAttribute("focusable", "false");
  if (className) svg.setAttribute("class", className);
  const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
  path.setAttribute("fill", "currentColor");
  path.setAttribute("d", icon.path);
  svg.append(path);
  return svg;
}

export function faHtml(name, className = "app-icon") {
  const icon = FA_ICONS[name];
  if (!icon) return "";
  const cls = className ? ` class="${className}"` : "";
  return `<svg${cls} viewBox="${icon.viewBox}" aria-hidden="true" focusable="false"><path fill="currentColor" d="${icon.path}"/></svg>`;
}
